--
-- Disparadores `cuentas_bancarias`
--
DELIMITER $$
CREATE TRIGGER `cuenta_maestra_unica_before_insert` BEFORE INSERT ON `cuentas_bancarias` FOR EACH ROW BEGIN
    IF NEW.`cuenta_maestra` = TRUE THEN
        IF EXISTS (SELECT 1 FROM `cuentas_bancarias` WHERE `cuenta_maestra` = TRUE) THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'YaExisteCuentaMaestra';
        END IF;
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `cuenta_maestra_unica_before_update` BEFORE UPDATE ON `cuentas_bancarias` FOR EACH ROW BEGIN
    IF NEW.`cuenta_maestra` = TRUE THEN
        IF EXISTS (SELECT 1 FROM `cuentas_bancarias` WHERE `cuenta_maestra` = TRUE AND OLD.`cuenta_maestra` = FALSE) THEN
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'YaExisteCuentaMaestra';
        END IF;
    END IF;
END
$$
DELIMITER ;

